function renderTextbookLink(label: string, doc: string, printed: number, physical: number) {
  assertTextbookLocator(doc, printed, physical);
  return `<button class="text-link" type="button" data-open-textbook="${doc}" data-printed-page="${printed}" data-pdf-page="${physical}">${escapeHtml(label)}</button>`;
}

function textbookReviewFor(routeId: TextbookReviewSupportV1["routeId"]) {
  const record = TEXTBOOK_REVIEW_SUPPORT.find((entry) => entry.routeId === routeId);
  if (!record) throw new Error(`Missing textbook review support for ${routeId}.`);
  return record;
}

function renderTextbookReviewSupport(record: TextbookReviewSupportV1) {
  const panelId = `${record.routeId}-textbook-answer-guide`;
  return `<section class="textbook-review-support" data-textbook-review-route="${record.routeId}" aria-labelledby="${record.routeId}-textbook-review-title">
    <div class="textbook-review-intro">
      <p class="section-label">${escapeHtml(record.eyebrow)}</p>
      <h2 id="${record.routeId}-textbook-review-title">${escapeHtml(record.title)}</h2>
      ${record.context ? `<p>${escapeHtml(record.context)}</p>` : ""}
      <p>${escapeHtml(record.assignment)}</p>
      <p class="textbook-review-note">This is optional extra review. Use it to strengthen the ideas you want to revisit before the course questions.</p>
      <div class="textbook-review-links">${record.pageLinks.map((link) => renderTextbookLink(link.label, link.documentId, link.printedPage, link.physicalPage)).join("")}<button class="text-link" type="button" data-question-jump="${record.jumpTargetId}">${escapeHtml(record.jumpLabel)}</button></div>
    </div>
    <div class="textbook-review-reveal">
      <button class="button button--secondary" type="button" data-textbook-review-attempt="${record.attemptId}" aria-expanded="false" aria-controls="${panelId}">I attempted the textbook review</button>
      <span data-textbook-review-status="${record.attemptId}" aria-live="polite">The answer guide opens after you confirm an attempt.</span>
    </div>
    <div class="textbook-review-answer-guide" id="${panelId}" data-textbook-review-answer="${record.attemptId}" hidden>
      <h3 tabindex="-1">Check your work</h3>
      <ol class="textbook-review-answer-list">${record.answers.map((answer, index) => `<li value="${record.questionNumbers[index]}"><strong>Q${record.questionNumbers[index]}.</strong> ${escapeHtml(answer)}</li>`).join("")}</ol>
      <button class="button button--secondary" type="button" data-textbook-review-hide="${record.attemptId}">Hide answer guide</button>
    </div>
  </section>`;
}

function renderPracticeItem(original: PracticeItem) {
  const item = correctPracticeItem(original);
  const workId = processPracticeWorkId(item.id);
  const choices = Object.entries(item.choices).map(([value, label]) => `<label class="choice-row"><input type="radio" name="${item.id}" value="${value}"><span>${escapeHtml(label)}</span></label>`).join("");
  const feedbackEntries = "feedback" in item ? item.feedback : {};
  return `<article class="practice-item${item.optional ? " practice-item--challenge" : ""}" data-practice-id="${item.id}" data-required="${item.optional ? "false" : "true"}" data-process-work-source="${workId}">
    <p class="practice-number">Question ${item.number}</p>
    <h3 id="work-focus-${workId}" tabindex="-1">${escapeHtml(item.prompt)}</h3>
    <p data-previous-practice-answer data-legacy-choices='${escapeHtml(JSON.stringify(item.legacyChoices))}' hidden></p>
    <fieldset><legend class="sr-only">Choose one answer</legend>${choices}</fieldset>
    <button class="button button--secondary" type="button" data-check-practice>Check answer</button>
    <div class="practice-feedback" data-practice-feedback hidden aria-live="polite"
      data-answer="${item.answer}"
      data-rationale="${escapeHtml(item.rationale)}"
      data-feedback='${escapeHtml(JSON.stringify(feedbackEntries))}'>
      <p data-feedback-message></p>
      <p>${renderTextbookLink(`${item.explanation.support === "background" ? "Textbook background" : "Find this idea in the textbook"} on p. ${item.textbook.printed}`, item.textbook.doc, item.textbook.printed, item.textbook.physical)}</p>
      <p>${item.explanation.advancedId ? `<a href="#${item.explanation.lessonId}/advanced/${item.explanation.advancedId}">Revisit the Advanced Learning explanation</a>` : `<button type="button" class="text-link" data-open-first-use="${item.explanation.localTarget}" data-first-use-route="${item.explanation.lessonId}">Revisit the lesson explanation</button>`}</p>
    </div>
  </article>`;
}

function renderFigure(input: { id: string; title: string; src: string; alt: string; description: string; width?: number; height?: number }) {
  return `<figure class="science-figure" data-figure-id="${input.id}">
    <div class="figure-toolbar"><p>${escapeHtml(input.title)}</p><button type="button" class="button button--quiet" data-enlarge-figure aria-label="View ${escapeHtml(input.title)} larger">View larger</button></div>
    <img src="${input.src}" alt="${escapeHtml(input.alt)}" width="${input.width ?? 1586}" height="${input.height ?? 992}" loading="lazy" decoding="async">
    <figcaption><strong>Read the figure:</strong> ${escapeHtml(input.description)}</figcaption>
  </figure>`;
}

