function vocabularyUnlock(entry: VocabularyEntry) {
  const lessonNumbers = entry.primaryLessonIds
    .map((id) => id.match(/^lesson-(\d+)$/)?.[1])
    .filter((value): value is string => Boolean(value))
    .map(Number);
  if (lessonNumbers.length) {
    const order = Math.min(...lessonNumbers);
    return { order, routeId: `lesson-${String(order).padStart(2, "0")}`, label: `Lesson ${order}` };
  }
  return { order: 14, routeId: "review-seminar", label: "Review Seminar" };
}

