function renderGraphDataTable(graph: ModelGraph, captionPrefix = "Data for") {
  return `<div class="model-data-table" role="region" aria-label="${escapeHtml(graph.title)} data table" tabindex="0"><table><caption>${escapeHtml(captionPrefix)} ${escapeHtml(graph.title.toLowerCase())}</caption><thead><tr><th scope="col">${escapeHtml(graph.xLabel)}</th>${graph.series.map((series) => `<th scope="col">${escapeHtml(series.label)}</th>`).join("")}</tr></thead><tbody>${graph.xValues.map((value, index) => `<tr><th scope="row">${escapeHtml(value)}</th>${graph.series.map((series) => `<td>${escapeHtml(series.values[index])}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
}

function renderGraphMarker(series: ModelGraph["series"][number], x: number, y: number, highlighted: boolean) {
  const common = `fill="${series.color}" stroke="${highlighted ? "#171b1b" : "#fff"}" stroke-width="${highlighted ? 4 : 2}"`;
  if (series.symbol === "square") return `<rect x="${(x - (highlighted ? 7 : 5)).toFixed(1)}" y="${(y - (highlighted ? 7 : 5)).toFixed(1)}" width="${highlighted ? 14 : 10}" height="${highlighted ? 14 : 10}" ${common}/>`;
  if (series.symbol === "triangle") return `<path d="M${x.toFixed(1)} ${(y - (highlighted ? 9 : 7)).toFixed(1)}L${(x + (highlighted ? 9 : 7)).toFixed(1)} ${(y + (highlighted ? 8 : 6)).toFixed(1)}H${(x - (highlighted ? 9 : 7)).toFixed(1)}Z" ${common}/>`;
  return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${highlighted ? 8 : 5}" ${common}/>`;
}

function renderModelGraph(graph: ModelGraph, id: string) {
  const width = 760;
  const height = 360;
  const left = 74;
  const right = 24;
  const top = 50;
  const bottom = 70;
  const plotWidth = width - left - right;
  const plotHeight = height - top - bottom;
  const xAt = (index: number) => left + (graph.xValues.length === 1 ? plotWidth / 2 : (index / (graph.xValues.length - 1)) * plotWidth);
  const yAt = (value: number) => {
    const ratio = (value - graph.yMin) / (graph.yMax - graph.yMin);
    return top + (graph.invertY ? ratio : 1 - ratio) * plotHeight;
  };
  const highlighted = new Set(graph.highlightIndices ?? []);
  const safeId = id.replace(/[^a-z0-9-]/gi, "-");
  const grid = graph.yTicks.map((tick) => {
    const y = yAt(tick);
    return `<g><line x1="${left}" y1="${y.toFixed(1)}" x2="${width - right}" y2="${y.toFixed(1)}" stroke="#d4d9d5" stroke-width="1"/><text x="${left - 12}" y="${(y + 5).toFixed(1)}" text-anchor="end">${escapeHtml(tick)}</text></g>`;
  }).join("");
  const xTicks = graph.xValues.map((value, index) => `<g><line x1="${xAt(index).toFixed(1)}" y1="${height - bottom}" x2="${xAt(index).toFixed(1)}" y2="${height - bottom + 6}" stroke="#535b58"/><text x="${xAt(index).toFixed(1)}" y="${height - bottom + 25}" text-anchor="middle">${escapeHtml(value)}</text></g>`).join("");
  const lines = graph.series.map((series) => {
    const points = series.values.map((value, index) => `${xAt(index).toFixed(1)},${yAt(value).toFixed(1)}`).join(" ");
    const markers = series.values.map((value, index) => renderGraphMarker(series, xAt(index), yAt(value), highlighted.has(index))).join("");
    return `<polyline points="${points}" fill="none" stroke="${series.color}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${markers}`;
  }).join("");
  return `<figure class="model-graph" data-model-graph><div class="model-graph__legend" aria-hidden="true">${graph.series.map((series) => `<span><i data-symbol="${series.symbol}" style="--series:${series.color}"></i>${escapeHtml(series.label)}</span>`).join("")}</div><svg viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="${safeId}-title ${safeId}-desc"><title id="${safeId}-title">${escapeHtml(graph.title)}</title><desc id="${safeId}-desc">${escapeHtml(graph.description)}</desc><g class="model-graph__ticks" font-family="Work Sans, sans-serif" font-size="13" fill="#343a38">${grid}${xTicks}</g><line x1="${left}" y1="${top}" x2="${left}" y2="${height - bottom}" stroke="#535b58" stroke-width="2"/><line x1="${left}" y1="${height - bottom}" x2="${width - right}" y2="${height - bottom}" stroke="#535b58" stroke-width="2"/>${lines}<text class="model-graph__axis" x="${left + plotWidth / 2}" y="${height - 12}" text-anchor="middle">${escapeHtml(graph.xLabel)}</text><text class="model-graph__axis" transform="translate(18 ${top + plotHeight / 2}) rotate(-90)" text-anchor="middle">${escapeHtml(graph.yLabel)}</text></svg><figcaption>${escapeHtml(graph.note)}</figcaption>${renderGraphDataTable(graph)}</figure>`;
}

function renderModelPath(choice: ModelLabChoice) {
  if (!choice.path?.length) return "";
  return `<ol class="model-result-flow" aria-label="Pathway for ${escapeHtml(choice.label)}">${choice.path.map((step) => `<li>${escapeHtml(step)}</li>`).join("")}</ol>`;
}

function renderModelResult(model: ModelLabRecord, choice: ModelLabChoice) {
  return `<div class="model-result-copy"><p class="model-result-kicker">Evidence from the model</p><h3>${escapeHtml(choice.resultTitle)}</h3><dl class="model-evidence-grid">${choice.evidence.map((item) => `<div><dt>${escapeHtml(item.label)}</dt><dd>${escapeHtml(item.value)}</dd></div>`).join("")}</dl><p><strong>What changed:</strong> ${escapeHtml(choice.observation)}</p><p><strong>Why it changed:</strong> ${escapeHtml(choice.reasoning)}</p></div>${choice.graph ? renderModelGraph(choice.graph, `${model.id}-${choice.id}-graph`) : renderModelPath(choice)}<p class="model-next-question"><strong>Think next:</strong> ${escapeHtml(choice.nextQuestion)}</p>`;
}

function renderStaticModelEquivalent(model: ModelLabRecord) {
  return `<details class="model-static-equivalent"><summary>Use the complete static equivalent</summary><div><p>${escapeHtml(model.staticEquivalent)}</p>${model.choices.map((choice) => `<section><h3>${escapeHtml(choice.label)}</h3><p><strong>Result:</strong> ${escapeHtml(choice.resultTitle)}</p><p>${escapeHtml(choice.observation)} ${escapeHtml(choice.reasoning)}</p>${choice.graph ? renderGraphDataTable(choice.graph, "Values for") : choice.path ? `<p><strong>Path:</strong> ${escapeHtml(choice.path.join(" → "))}</p>` : ""}</section>`).join("")}</div></details>`;
}

function renderChapter11Study(modelId: string) {
  return CHAPTER_11_STUDY_TASKS.filter(task => task.modelId === modelId).map(task => {
    let visual = task.visual === "voltage" ? actionPotentialFigure("study-voltage-graph", true) : studyDiagram(task);
    if (task.visual === "brain") {
      const source = renderSvgVisual({ kind: "svg", id: "study-brain", title: task.title, variant: "brain-anatomy", description: task.description });
      visual = source.match(/<svg[\s\S]*?<\/svg>/)![0]
        .replace(/brain-title/g, "study-brain-title").replace(/brain-desc/g, "study-brain-desc")
        .replace(/<desc[^>]*>[\s\S]*?<\/desc>/, `<desc id="study-brain-desc">${escapeHtml(task.description)}</desc>`);
      ["Frontal lobe", "Parietal lobe", "Temporal lobe", "Occipital lobe", "Cerebellum", "Thalamus", "Hypothalamus", "Pons", "Medulla oblongata", "Spinal cord"].forEach((label, index) => { visual = visual.replace(`>${label}</text>`, `>${String.fromCharCode(65 + index)}</text>`); });
    }
    if (task.visual !== "voltage") visual = `<figure class="diagram-card semantic-figure science-figure--svg" data-figure-id="study-${task.id}"><div class="figure-toolbar"><p>${escapeHtml(task.title)}</p>${visual.startsWith("<svg") ? '<button class="button button--quiet" type="button" data-enlarge-figure>View larger</button>' : ""}</div>${visual}<figcaption>${escapeHtml(task.description)}</figcaption></figure>`;
    const responseId = studyResponseId(task.id);
    return `<details class="study-task" data-study-task="${task.id}"><summary><h3 id="study-${task.id}-heading" tabindex="-1">${escapeHtml(task.title)}</h3></summary><div class="study-task-body"><p>${escapeHtml(task.prompt)}</p>${visual}<label class="model-response" for="study-${task.id}-response"><strong>Your diagram notes</strong><span>${escapeHtml(task.frame)}</span><textarea id="study-${task.id}-response" data-response-id="${responseId}" data-study-response="${task.id}" maxlength="${task.maxLength}" rows="7" aria-describedby="study-${task.id}-save"></textarea></label><p id="study-${task.id}-save" data-save-status="${responseId}">Write a draft to save it with this model in Process Collection. This work is not graded.</p><details data-study-guide="${task.id}" hidden><summary>Compare with the explanation</summary>${task.guide.map(line => `<p>${escapeHtml(line)}</p>`).join("")}<p>Use this comparison to revise your notes. Opening it does not mark your response correct or overwrite your work.</p></details></div></details>`;
  }).join("");
}

function renderModelLab() {
  const chapters = [11, 12, 13] as const;
  const navigation = chapters.map((chapter) => `<section><h2>Chapter ${chapter}</h2>${MODEL_LAB_RECORDS.filter((model) => model.chapter === chapter).map((model, index) => `<button type="button" data-model-select="${model.id}" aria-pressed="${chapter === 11 && index === 0 ? "true" : "false"}"><span>${escapeHtml(model.title)}</span><small>${escapeHtml(model.lessonLabel)}</small></button>`).join("")}</section>`).join("");
  const panels = MODEL_LAB_RECORDS.map((model, index) => {
    const predictionId = `model-${model.id}-prediction`;
    const explanationId = `model-${model.id}-explanation`;
    return `<article class="model-panel" data-model-panel="${model.id}" data-model-kind="${model.kind}" data-model-lesson="${model.lessonId}" data-process-work-source="model-${model.id}" tabindex="-1" ${index ? "hidden" : ""}>
      <p class="section-label">${escapeHtml(model.lessonLabel)} investigation</p>
      <h2 id="work-focus-model-${model.id}" tabindex="-1">${escapeHtml(model.title)}</h2>
      ${renderChapter11Study(model.id)}
      ${renderOnlineStudies(model.id)}
      <section class="model-orientation" aria-labelledby="model-${model.id}-question">
        <p class="model-orientation__label">Investigation question</p>
        <h3 id="model-${model.id}-question">${escapeHtml(model.investigationQuestion)}</h3>
        <p><strong>What you are learning:</strong> ${escapeHtml(model.learningPurpose)}</p>
        <dl class="model-plan">
          <div><dt>What you change</dt><dd>${escapeHtml(model.testVariable)}</dd></div>
          <div><dt>What stays the same</dt><dd>${escapeHtml(model.comparisonControl)}</dd></div>
          <div><dt>Evidence to examine</dt><dd>${escapeHtml(model.evidenceFocus)}</dd></div>
        </dl>
      </section>
      <section class="model-mechanism" aria-labelledby="model-${model.id}-mechanism">
        <p class="model-stage-label">Before you investigate</p>
        <h3 id="model-${model.id}-mechanism">Review the base mechanism</h3>
        <p>${escapeHtml(model.reasoningAction)}</p>
        <ol class="model-path" aria-label="Base mechanism">${model.steps.map((step) => `<li data-model-step><div class="model-step-copy"><strong>${escapeHtml(step.label)}</strong><span>${escapeHtml(step.detail)}</span></div></li>`).join("")}</ol>
      </section>
      <div class="model-use-sequence" aria-label="Investigation sequence"><span>1. Predict</span><span>2. Test</span><span>3. Explain</span><span>4. Save</span></div>
      <section class="model-workflow-step model-workflow-step--predict" aria-labelledby="model-${model.id}-predict-heading">
        <p class="model-stage-label">Step 1</p>
        <h3 id="model-${model.id}-predict-heading">Choose a case and make a prediction</h3>
        <p class="model-prompt">${escapeHtml(model.prompt)}</p>
        <div class="model-controls" role="group" aria-label="Choose a case or phase to investigate">${model.choices.map((choice) => `<button class="button button--secondary" type="button" data-model-choice="${choice.id}" data-affected-step="${choice.affectedStep}" aria-pressed="false">${escapeHtml(choice.label)}</button>`).join("")}</div>
        <label class="model-response" for="${predictionId}"><strong>Your prediction</strong><span>${escapeHtml(model.predictionPrompt)}</span><textarea id="${predictionId}" rows="3" maxlength="180" data-model-prediction="${model.id}" placeholder="Write one or two clear sentences." disabled></textarea></label>
        <div class="model-test-row"><button class="button" type="button" data-test-model="${model.id}" disabled>Test my prediction</button><span data-model-test-status="${model.id}" aria-live="polite">Choose a case, then write your prediction.</span></div>
      </section>
      <section class="model-workflow-step" aria-labelledby="model-${model.id}-evidence-heading">
        <p class="model-stage-label">Step 2</p>
        <h3 id="model-${model.id}-evidence-heading">Examine the evidence</h3>
        <div class="model-output" data-model-output aria-live="polite"><div class="model-empty"><h3>No result yet</h3><p>Your evidence will appear here after you choose a case, write a prediction, and select <strong>Test my prediction</strong>.</p></div></div>
        <div class="model-result-templates" hidden><template data-model-empty><div class="model-empty"><h3>No result yet</h3><p>Your evidence will appear here after you choose a case, write a prediction, and select <strong>Test my prediction</strong>.</p></div></template>${model.choices.map((choice) => `<template data-model-result="${choice.id}" data-result-type="${choice.graph ? "graph" : choice.path ? "pathway" : "evidence"}" data-has-data-table="${choice.graph ? "true" : "false"}">${renderModelResult(model, choice)}</template>`).join("")}</div>
        ${renderStaticModelEquivalent(model)}
      </section>
      <section class="model-workflow-step model-workflow-step--explain" aria-labelledby="model-${model.id}-explain-heading">
        <p class="model-stage-label">Step 3</p>
        <h3 id="model-${model.id}-explain-heading">Explain what the evidence means</h3>
        <label class="model-response" for="${explanationId}"><strong>Your evidence-based explanation</strong><span>${escapeHtml(model.explanationPrompt)}</span><textarea id="${explanationId}" rows="4" maxlength="240" data-model-explanation="${model.id}" placeholder="Make a claim, cite model evidence, and connect it to the mechanism." disabled></textarea></label>
      </section>
      <section class="model-workflow-step model-workflow-step--save" aria-labelledby="model-${model.id}-save-heading">
        <p class="model-stage-label">Step 4</p>
        <h3 id="model-${model.id}-save-heading">Save the investigation you can explain</h3>
        <p>Your saved record includes the question, prediction, tested case, model evidence, and your explanation.</p>
        <div class="save-row model-save-row"><button class="button" type="button" data-collect-model="${model.id}" disabled>Save my investigation to Process Collection</button><button class="button button--secondary" type="button" data-reset-model="${model.id}" disabled>Reset this investigation</button><button class="text-link" type="button" data-page-target="${model.lessonId}">Return to ${escapeHtml(model.lessonLabel)}</button><span data-model-save-status="${model.id}" aria-live="polite">Choose a case and make a prediction first.</span></div>
      </section>
    </article>`;
  }).join("");
  return `<section id="model-lab" class="course-page hub-page" hidden><header class="page-header"><p class="eyebrow">Process Collection</p><h1>Models and Data Lab</h1><p>Use each model to answer one clear scientific question. Choose what to change, predict the result, test it against the model, explain the evidence, and save your investigation when it shows your thinking.</p><p class="vocab-progress"><strong data-model-progress>0 of 13</strong> investigations saved</p></header><div class="model-lab-layout"><nav aria-label="Lesson investigations">${navigation}</nav><div>${panels}</div></div></section>`;
}

function renderOverview(lessons: Pilot2Lesson[]) {
  return `<section id="overview" class="course-page overview-page"><header class="overview-hero"><p class="eyebrow">Biology 30 · Unit A</p><h1>How does your body detect change and coordinate a response?</h1><p>The nervous and endocrine systems use different signals, but they solve the same problem: keeping internal conditions within workable ranges while the world changes around you.</p><a class="button" href="#lesson-01" data-page-target="lesson-01">Begin with Neuron Structure</a></header><section class="overview-intro" aria-labelledby="course-route"><div><p class="section-label">Your route</p><h2 id="course-route">Learn one topic at a time</h2><p>The unit follows the same order as your class notes: Chapter 11 nervous-system topics, Chapter 12 sensory topics, and Chapter 13 endocrine topics.</p></div><ol><li><strong>13 lessons</strong><span>Learn, see a model, retrieve, practise, and save evidence.</span></li><li><strong>3 chapter practices</strong><span>Use feedback and exact textbook pages to repair gaps.</span></li><li><strong>Review Seminar</strong><span>Connect the chapters through worked cases.</span></li><li><strong>Final Practice</strong><span>Complete 18 core items; six Diploma Challenge items are optional.</span></li></ol></section><section class="chapter-roadmap" aria-labelledby="chapter-roadmap"><p class="section-label">Course map</p><h2 id="chapter-roadmap">Three chapters, one control story</h2>${[11,12,13].map((chapter) => `<article><h3>Chapter ${chapter}</h3><ol>${lessons.filter((lesson) => lesson.chapter === chapter).map((lesson) => `<li>${lesson.order}. ${escapeHtml(lesson.title)}</li>`).join("")}</ol></article>`).join("")}</section><aside class="unit-safety"><h2>Work safely</h2><p>Use supplied data whenever materials, a partner, consent, comfort, or supervision are not available. Course activities and synthetic health data are for learning, not diagnosis.</p></aside></section>`;
}

function renderGlossary(entries: VocabularyEntry[]) {
  const termRows = [...new Map(entries.flatMap((entry) => entry.familyTerms.map((term) => [term.toLowerCase(), { term, meaning: entry.learnerDefinition }]))).values()].slice(0, 109);
  return `<section id="glossary-and-data" class="course-page hub-page" hidden><header class="page-header"><p class="eyebrow">Resources</p><h1>Glossary and Data</h1><p>Use this quick reference when a label or supporting term appears. Core Vocabulary is where you build the larger concept relationships.</p></header><label class="glossary-search">Search the glossary<input type="search" data-glossary-search placeholder="Search a term"></label><dl class="glossary-list">${termRows.map(({ term, meaning }) => `<div data-glossary-row data-search="${escapeHtml(term.toLowerCase())}"><dt>${escapeHtml(term)}</dt><dd>${escapeHtml(meaning)}</dd></div>`).join("")}</dl><section class="data-reference"><h2>Unit data reminders</h2><table><caption>Values and labels used in this unit</caption><tbody><tr><th>Resting membrane potential</th><td>Approximately −70 mV in the course model</td></tr><tr><th>Blood-glucose data</th><td>Units and reference ranges are supplied with each case</td></tr><tr><th>Instructional datasets</th><td>Clearly labelled as sourced or synthetic</td></tr></tbody></table></section></section>`;
}

function renderSources() {
  return `<section id="sources-and-credits" class="course-page hub-page" hidden><header class="page-header"><p class="eyebrow">Resources</p><h1>Sources and Credits</h1><p>This course combines Alberta curriculum guidance with the class notes, local textbook chapters, and reviewed media.</p></header><section class="source-list"><article><h2>Curriculum</h2><p>Alberta Biology 20–30 Program of Studies and Biology 30 Student-based Performance Standards guide required learning and practice.</p></article><article><h2>Course materials</h2><p>Teacher daily plans and Unit A Chapter 11–13 notes guide topic order. Textbook pages are available locally in the Textbook Library.</p></article><article><h2>Figures</h2><p>Course diagrams are original redraws or teacher-authorized generated illustrations used for private course development. Each figure includes an adjacent explanation.</p></article><article><h2>Videos and illustrated walkthroughs</h2><p>Video titles, providers, and direct YouTube links appear beside each preview. Every required checkpoint also has a complete illustrated course pathway.</p></article></section><section class="collection-section"><h2>Nervous-system study diagrams</h2><p>The neuron, voltage and tissue tasks use course-authored diagrams. The brain identification task reuses the lesson schematic. Scientific checks use OpenStax <a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/12-2-nervous-tissue" target="_blank" rel="noopener">Nervous Tissue</a>, <a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/12-4-the-action-potential" target="_blank" rel="noopener">The Action Potential</a>, and <a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/13-2-the-central-nervous-system" target="_blank" rel="noopener">The Central Nervous System</a>.</p></section><p>The real spinal-cord micrograph is <a href="https://phil.cdc.gov/Details.aspx?pid=2756" target="_blank" rel="noopener">CDC PHIL image 2756</a>, credited to CDC / Dr. Karp, Emory University. Local model observations use this image with an explanation of its limits. The CDC does not endorse this course.</p><p>Video excerpts are paired with local clarification notes and complete illustrated walkthroughs. Use the course wording for accurate labels when automatic captions miss a scientific term.</p></section>`;
}

