  function clone(value){return JSON.parse(JSON.stringify(value))}
  function normalize(raw){var next=Object.assign(clone(defaultState),raw||{});next.responses=raw&&raw.responses&&typeof raw.responses==="object"?raw.responses:{};next.practice=raw&&raw.practice&&typeof raw.practice==="object"?raw.practice:{};next.completedRoutes=Array.isArray(next.completedRoutes)?next.completedRoutes.filter(function(id){return REQUIRED_ROUTES.indexOf(id)>=0}).slice(0,18):[];next.visitedLessons=Array.isArray(next.visitedLessons)?next.visitedLessons.filter(function(id){return LESSON_ORDER[id]}):[];next.investigations=Array.isArray(next.investigations)?next.investigations.filter(function(id){return [COURSE+":investigation:reflex-response",COURSE+":investigation:sensory-receptors",COURSE+":investigation:endocrine-data"].indexOf(id)>=0}):[];next.evidenceIds=Array.isArray(next.evidenceIds)?next.evidenceIds.filter(function(id){return LESSON_IDS.some(function(lessonId){return id===COURSE+":"+lessonId+":evidence-slip"})}):[];next.vocabulary=Object.assign(clone(defaultState.vocabulary),next.vocabulary||{});next.vocabulary.choiceIds=Array.isArray(next.vocabulary.choiceIds)?next.vocabulary.choiceIds.slice(0,2):[];next.vocabulary.collectedIds=Array.isArray(next.vocabulary.collectedIds)?next.vocabulary.collectedIds.filter(function(id){return FIXED_VOCAB.indexOf(id)>=0||next.vocabulary.choiceIds.indexOf(id)>=0}).slice(0,8):[];return next}
  function scormApi(){var current=window;for(var i=0;i<8&&current;i+=1){try{if(current.API_1484_11)return current.API_1484_11;if(current.parent===current)break;current=current.parent}catch(_error){break}}return null}
  function load(){var raw="";var api=scormApi();try{if(api){api.Initialize("");raw=api.GetValue("cmi.suspend_data")||""}}catch(_error){}if(!raw)raw=localStorage.getItem(STORAGE)||"";try{return normalize(raw?JSON.parse(raw):null)}catch(_error){return normalize(null)}}
  var state=load();
  function announce(message){var node=document.querySelector("[data-save-toast]");if(!node)return;node.textContent=message;clearTimeout(announce.timer);announce.timer=setTimeout(function(){node.textContent=""},1800)}
  function save(){var serialized=JSON.stringify(state);if(serialized.length>STATE_LIMIT){announce("Save limit reached. Your last valid save is still safe.");return false}try{localStorage.setItem(STORAGE,serialized);lastValid=serialized;var api=scormApi();if(api){api.SetValue("cmi.suspend_data",serialized);api.SetValue("cmi.location",state.route);api.SetValue("cmi.progress_measure",String(state.completedRoutes.length/18));api.SetValue("cmi.completion_status",state.completedRoutes.length===18?"completed":"incomplete");var finalItems=Array.from(document.querySelectorAll('#final-practice [data-practice-id][data-required="true"]'));if(finalItems.length===18&&finalItems.every(function(item){return practiceSubmitted(item.getAttribute("data-practice-id"))})){var correct=finalItems.filter(function(item){return state.practice[item.getAttribute("data-practice-id")].correct}).length;api.SetValue("cmi.score.min","0");api.SetValue("cmi.score.max","100");api.SetValue("cmi.score.raw",String(Math.round(correct/18*100)));api.SetValue("cmi.success_status","unknown")}api.Commit("")}return true}catch(_error){if(lastValid)try{localStorage.setItem(STORAGE,lastValid)}catch(_ignore){}announce("Save failed. Copy your work before leaving.");return false}}
  window.nextStepEvidenceBank={list:function(filters){var responseId=filters&&filters.responseId;return state.evidenceIds.filter(function(id){return !responseId||id===responseId}).map(function(id){return {contributionId:id,responseId:id,evidence:String(state.responses[id]||"")}})},upsert:function(entry){var id=entry&&(entry.contributionId||entry.responseId);if(!id)return false;if(entry.evidence!==undefined)state.responses[id]=String(entry.evidence);if(state.evidenceIds.indexOf(id)<0)state.evidenceIds.push(id);return save()},remove:function(id){var index=state.evidenceIds.indexOf(id);if(index<0)return false;state.evidenceIds.splice(index,1);save();return true}};
  lastValid=JSON.stringify(state);
  function topLevelRoute(id){return document.getElementById(id)&&document.getElementById(id).classList.contains("course-page")}
  function showRoute(id,options){if(!topLevelRoute(id))id="overview";document.querySelectorAll(".course-page").forEach(function(page){page.hidden=page.id!==id});document.querySelectorAll("[data-page-target]").forEach(function(link){link.classList.toggle("active",link.getAttribute("data-page-target")===id)});state.route=id;if(LESSON_ORDER[id]&&state.visitedLessons.indexOf(id)<0)state.visitedLessons.push(id);if(location.hash!=="#"+id)history.replaceState(null,"","#"+id);save();updateProgress();updateVocabulary();loadVisibleVideos();document.querySelector(".sidebar").classList.remove("is-open");document.querySelector(".menu-scrim").hidden=true;document.body.classList.remove("nav-open");window.scrollTo(0,0);if(options&&options.focus){var target=document.querySelector(options.focus);if(target){target.setAttribute("tabindex","-1");target.focus();target.scrollIntoView({block:"start"})}}}
  function updateProgress(){var count=state.completedRoutes.length;document.querySelector("[data-progress-count]").textContent=count+" of 18 required routes";document.querySelector("[data-progress-fraction]").textContent=count+" / 18";document.querySelector("[data-progress-percent]").textContent=Math.round(count/18*100)+"%";document.querySelector("[data-progress-fill]").style.width=(count/18*100)+"%";document.querySelectorAll("[data-route-status]").forEach(function(node){var id=node.getAttribute("data-route-status");var done=state.completedRoutes.indexOf(id)>=0;node.textContent=done?"Complete":"In progress";node.closest(".lesson-completion").classList.toggle("is-complete",done)});updateCompletionButtons()}
  function practiceSubmitted(id){return Boolean(state.practice[id]&&state.practice[id].submitted)}
  function updateCompletionButtons(){LESSON_IDS.forEach(function(id){var page=document.getElementById(id);if(!page)return;var evidence=String(state.responses[COURSE+":"+id+":evidence-slip"]||"").trim();var items=Array.from(page.querySelectorAll('[data-practice-id][data-required="true"]')).map(function(node){return node.getAttribute("data-practice-id")});var ready=evidence.length>0&&items.length===2&&items.every(practiceSubmitted);var button=document.querySelector('[data-complete-route="'+id+'"]');if(button)button.disabled=!ready});["chapter-11-practice","chapter-12-practice","chapter-13-practice"].forEach(function(id){var page=document.getElementById(id);var button=document.querySelector('[data-complete-route="'+id+'"]');if(page&&button){var items=Array.from(page.querySelectorAll('[data-practice-id][data-required="true"]'));button.disabled=items.length!==12||!items.every(function(node){return practiceSubmitted(node.getAttribute("data-practice-id"))})}});var seminarButton=document.querySelector('[data-complete-route="review-seminar"]');if(seminarButton){var sessions=["nervous","sensory","endocrine"].map(function(id){return String(state.responses[COURSE+":review-seminar:"+id]||"").trim()});seminarButton.disabled=!sessions.every(Boolean)}var finalButton=document.querySelector('[data-complete-route="final-practice"]');if(finalButton){var finalItems=Array.from(document.querySelectorAll('#final-practice [data-practice-id][data-required="true"]'));finalButton.disabled=finalItems.length!==18||!finalItems.every(function(node){return practiceSubmitted(node.getAttribute("data-practice-id"))})}}
  function previousPracticeAnswer(item,choice){var note=item.querySelector("[data-previous-practice-answer]");if(!note)return;var previous={};try{previous=JSON.parse(note.getAttribute("data-legacy-choices")||"{}")}catch(_error){}note.hidden=!Object.prototype.hasOwnProperty.call(previous,choice);note.textContent=note.hidden?"":"Your previous answer: “"+previous[choice]+"”. Your attempt is kept. You can try the updated choices below."}
  function restoreResponses(){document.querySelectorAll("[data-response-id]").forEach(function(field){var id=field.getAttribute("data-response-id");if(Object.prototype.hasOwnProperty.call(state.responses,id))field.value=state.responses[id]});document.querySelectorAll("[data-practice-id]").forEach(function(item){var id=item.getAttribute("data-practice-id");var saved=state.practice[id];if(saved&&saved.choice){var input=item.querySelector('input[value="'+CSS.escape(saved.choice)+'"]');if(input)input.checked=true;previousPracticeAnswer(item,saved.choice)}if(saved&&saved.submitted)showPracticeFeedback(item,saved.choice,false)});state.investigations.forEach(function(id){var status=document.querySelector('[data-investigation-status="'+id+'"]');if(status)status.textContent="Checkpoint saved"})}
  function persistField(field,announceSave){var id=field.getAttribute("data-response-id");if(!id)return;state.responses[id]=field.value.slice(0,Number(field.getAttribute("maxlength")||2000));save();var status=document.querySelector('[data-save-status="'+CSS.escape(id)+'"]');if(status)status.textContent=announceSave?"Saved":"Saved as you type";if(announceSave)announce("Work saved.");updateCompletionButtons();updateFrayer(field.closest("[data-frayer]"));renderCollections()}
