  function applyCollectionFilters(){var chapterControl=document.querySelector("[data-collection-chapter-filter]");var kindControl=document.querySelector("[data-collection-type-filter]");var chapter=chapterControl?chapterControl.value:"all";var kind=kindControl?kindControl.value:"all";var shown=0;document.querySelectorAll("[data-process-index-item]").forEach(function(item){var visible=(chapter==="all"||item.getAttribute("data-process-chapter")===chapter)&&(kind==="all"||item.getAttribute("data-process-kind")===kind);item.hidden=!visible;if(visible)shown+=1});document.querySelectorAll("[data-process-index-group]").forEach(function(group){group.hidden=!group.querySelector("[data-process-index-item]:not([hidden])")});var count=document.querySelector("[data-all-work-count]");var total=allProcessViews().length;if(count)count.textContent=shown===total?total+(total===1?" record":" records"):shown+" shown · "+total+" total";var root=document.querySelector("[data-all-work-list]");var filterEmpty=root&&root.querySelector("[data-filter-empty]");if(filterEmpty)filterEmpty.hidden=shown>0}
  function renderCollections(){var root=document.querySelector("[data-all-work-list]");var views=allProcessViews();if(root){if(!views.length){root.innerHTML='<p class="empty-state">Your started work will appear here. Begin with a lesson response, practice question, or investigation.</p>'}else{var chapters=[];views.forEach(function(view){if(chapters.indexOf(view.record.chapter)<0)chapters.push(view.record.chapter)});root.innerHTML=chapters.map(function(chapter){var chapterViews=views.filter(function(view){return view.record.chapter===chapter});return '<section class="process-work-group" data-process-index-group><h3>'+escapeText(chapterViews[0].record.chapterLabel)+'</h3>'+chapterViews.map(processItemHtml).join("")+"</section>"}).join("")+'<p class="empty-state" data-filter-empty hidden>No started work matches both filters.</p>'}applyCollectionFilters()}var modelProgress=document.querySelector("[data-model-progress]");if(modelProgress)modelProgress.textContent=state.models.collectedIds.length+" of "+knownModelIds().length}
  function collectionText(){var views=allProcessViews();if(!views.length)return "Process Collection\n\nNo work has been started yet.";return "Process Collection\n\n"+views.map(function(view){var lines=[view.record.chapterLabel+" · "+view.record.lessonLabel+" · "+view.record.activityType,"Status: "+view.status,"Task: "+view.record.prompt].concat(view.response.map(function(line){return "Response: "+line}));if(view.evidence.length)lines=lines.concat(view.evidence.map(function(line){return "Course feedback: "+line}));return lines.join("\n")}).join("\n\n")}
