  function openVocabulary(id){var button=document.querySelector('[data-vocabulary-target="'+id+'"]');if(!button)return;var unlocked=vocabularyUnlocked(button);var filter=document.querySelector("[data-vocabulary-filter]");if(!unlocked&&filter)filter.value="all";state.vocabulary.activeId=id;showRoute("core-vocabulary");updateVocabulary();var heading=document.querySelector('[data-vocabulary-entry="'+id+'"] h2');if(heading){heading.setAttribute("tabindex","-1");heading.focus();heading.scrollIntoView({block:"start"})}if(!unlocked)announce("Full details unlock after you begin "+button.getAttribute("data-unlock-label")+".")}
